        for c in range(W):
            if g[r][c] != 4:
                continue
            if r < line:
                nr = r + 1
            else:
                nr = max(r, line + 1) if r > line + 1 else r  # slide up to line+1
            if nr == line - 1:
                out[nr][c] = 4
                for dr in (1, -1):
                    k = 1
                    while 0 <= nr-k and 0 <= c+k*dr < W:
                        out[nr-k][c+k*dr] = 4; k += 1
            else:
                out[nr][c] = 4
    return out

